const raw = $input.first().json;
let task;
try { task = typeof raw.task === 'string' ? JSON.parse(raw.task) : raw.task; }
catch (e) { throw new Error('task is not valid JSON'); }
if (!task || typeof task !== 'object') throw new Error('task is missing');
for (const k of ['task_id', 'agent', 'goal']) {
  if (!task[k]) throw new Error('task missing ' + k);
}
task.mode = 'propose';          // this workflow can never run in another mode
task.inputs = task.inputs || {};
return [{ json: { user_id: raw.user_id, task } }];

const profile = $('Load profile').first().json;
const { task } = $('Parse task').first().json;
const j = (v, fallback) => {            // Data table JSON columns arrive as text
  try { return typeof v === 'string' ? JSON.parse(v) : (v ?? fallback); } catch (e) { return fallback; }
};
const tz = profile.tz || 'Asia/Kolkata';
const prefs = j(profile.preferences, {});
return [{ json: {
  task,
  ctx: {
    user_id: profile.user_id, user_name: profile.name, user_email: profile.email,
    tz, now: DateTime.now().setZone(tz).toISO(),
    working_hours: j(profile.working_hours, { start: '09:30', end: '18:30' }),
    calendars: j(profile.calendars, []), preferences: prefs,
    default_duration: prefs.default_duration || 30,
    buffer_minutes: prefs.buffer_minutes || 10,
    company_domains: prefs.company_domains || ['example.com'],   // replace with yours
    vip: prefs.vip || [], standing_approvals: j(profile.standing_approvals, [])
  }
} }];

const { task, ctx } = $('Build context').first().json;
const tw = (task.inputs && task.inputs.time_window) || {};
const end = tw.end ? DateTime.fromISO(tw.end) : DateTime.fromISO(ctx.now);
const start = tw.start ? DateTime.fromISO(tw.start)
  : end.minus({ hours: ctx.preferences.triage_window_hours || 24 });
return [{ json: { window_start: start.toISO(), window_end: end.toISO() } }];

const win = $('Window').first().json;
const ctx = $('Build context').first().json.ctx;
const actual = String($input.first().json.emailAddress || '').toLowerCase();
const expected = String(ctx.user_email || '').toLowerCase();
if (!actual) throw new Error('Cannot verify the connected Gmail account: profile lookup returned no address.');
if (expected && actual !== expected) throw new Error('Gmail credential is signed in as ' + actual + ' but the profile expects ' + expected + '. No mail was read.');
return [{ json: { ...win, mailbox: actual } }];

const ctx = $('Build context').first().json.ctx;
const me = String(ctx.user_email || '').toLowerCase();
const vip = (ctx.vip || []).map(v => String(v).toLowerCase());
// Works with both Gmail output shapes: the raw API payload (payload.headers list)
// and n8n's parsed message (headers object, from/to objects, labelIds, text).
const hdr = (m, name) => {
  // Prefer n8n's decoded fields (from.text, subject) over raw, possibly MIME-encoded headers
  const dec = m[name];
  if (typeof dec === 'string' && dec) return dec.replace(/\s+/g, ' ').trim();
  if (dec && typeof dec === 'object' && dec.text) return String(dec.text).replace(/\s+/g, ' ').trim();
  const hit = ((m.payload && m.payload.headers) || []).find(h => h.name.toLowerCase() === name);
  if (hit) return hit.value || '';
  if (m.headers && typeof m.headers === 'object' && typeof m.headers[name] === 'string') {
    return m.headers[name].replace(/^[A-Za-z-]+:\s*/, '');
  }
  const flat = m[name.charAt(0).toUpperCase() + name.slice(1)];
  return typeof flat === 'string' ? flat : '';
};
const noiseLabels = ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS'];
const isInvite = (s) => /^(updated )?invitation:|^(canceled|cancelled) event:|^(accepted|declined|tentatively accepted):/i.test(s);
const byThread = new Map();
let noiseDropped = 0;
// Fetch inbox always outputs one item; an empty inbox arrives as one empty item
const all = $input.all().filter(i => Object.keys(i.json).length > 0);
for (const { json: m } of all) {
  const from = hdr(m, 'from'), to = hdr(m, 'to').toLowerCase(), cc = hdr(m, 'cc').toLowerCase();
  const subject = hdr(m, 'subject');
  const labels = m.labelIds || (m.labels || []).map(l => l.id);
  const ts = m.internalDate ? Number(m.internalDate) : Date.parse(m.date || ctx.now);
  const row = {
    thread_id: m.threadId, message_id: m.id, from, subject,
    received: new Date(ts).toISOString(),
    snippet: String(m.snippet || m.text || '').replace(/\[?https?:\/\/\S+\]?/g, '').replace(/[\u034f\u00ad\u200c\u200b]/g, '').replace(/\s+/g, ' ').trim().slice(0, 240),
    direct_to_me: to.includes(me), cc_only: !to.includes(me) && cc.includes(me),
    is_vip: vip.some(v => from.toLowerCase().includes(v)),
    is_invite: isInvite(subject), unread: labels.includes('UNREAD'),
  };
  if (labels.some(l => noiseLabels.includes(l)) && !row.is_vip && !row.direct_to_me) { noiseDropped++; continue; }
  const prev = byThread.get(row.thread_id);
  if (!prev || prev.received < row.received) byThread.set(row.thread_id, row);
}
const rows = [...byThread.values()].sort((a, b) => b.received.localeCompare(a.received)).slice(0, 80);
return [{ json: { rows, noise_dropped: noiseDropped, fetched: all.length } }];

const out = $input.first().json.output || {};
const ctx = $('Build context').first().json.ctx;
const isExternal = (emails) => (emails || []).some(e => !ctx.company_domains.some(d => String(e).toLowerCase().endsWith('@' + d)));
const notes = [out.notes || ''];
const all = out.drafts || [];
let drafts = all.filter(d => d.draft_id && d.thread_id);
if (drafts.length < all.length) notes.push('Dropped drafts with no draft id or thread id.');
if (drafts.length > 8) { notes.push('More than 8 drafts were made; listing the first 8. The rest are in Gmail Drafts.'); drafts = drafts.slice(0, 8); }
const reqs = out.meeting_requests || [];
const needsScheduler = reqs.some(m => m.needs_scheduler) || drafts.some(d => /TIME OPTIONS FROM CALENDAR/.test(d.body_preview || ''));
return [{ json: {
  status: out.status,
  results: { counts: out.counts, urgent: out.urgent || [], meeting_requests: reqs, action_items: out.action_items || [],
    fyi_digest: (out.fyi_digest || []).slice(0, 5), noise_summary: out.noise_summary || '', needs_scheduler: needsScheduler },
  proposals: drafts.map(d => ({ action: 'send_draft', draft_id: d.draft_id, thread_id: d.thread_id, to: d.to || [],
    summary: d.summary, body_preview: d.body_preview, affects: d.to || [], external: isExternal(d.to) })),
  notes: notes.filter(Boolean).join(' ')
} }];

const meta = $('Validate output').first().json;
const checks = meta.proposals.length ? $input.all().map(i => i.json) : [];
const notes = [meta.notes];
const proposals = meta.proposals.filter((p, i) => {
  const c = checks[i] || {};
  const exists = !c.error && (c.id || (c.message && c.message.id));
  if (!exists) notes.push('Dropped a draft reply to ' + (p.to || []).join(', ') + ': draft ' + p.draft_id + ' was not found in Gmail.');
  return exists;
});
return [{ json: { ...meta, status: proposals.length < meta.proposals.length ? 'partial' : meta.status,
  proposals, notes: notes.filter(Boolean).join(' ') } }];

const meta = $input.first().json;                 // from Final proposals
const user_id = $('Parse task').first().json.user_id;
const agent = 'email';                             // hard-coded per workflow
const pid = (i) => String($execution.id) + '-' + (i + 1);   // Build response uses the same rule
return meta.proposals.map((p, i) => ({ json: {
  proposal_id: pid(i), user_id, agent,
  action: JSON.stringify(p), summary: p.summary, external: !!p.external, status: 'pending'
} }));

const meta = $('Final proposals').first().json;   // { status, results, proposals, notes }
const pid = (i) => String($execution.id) + '-' + (i + 1);   // same rule as Split proposals
return [{ json: {
  status: meta.status,
  results: meta.results,
  proposed_actions: meta.proposals.map((p, i) => ({
    proposal_id: pid(i), summary: p.summary, affects: p.affects || [], external: !!p.external
  })),
  notes: meta.notes || ''
} }];

