={{ JSON.stringify((() => {
  const s = $('Start trace').first().json;
  const task = s.task;
  const userId = s.user_id || ((task && typeof task === 'object') ? task.user_id : null) || null;
  const out = ($('Build response').isExecuted ? $('Build response') : $('Failure response')).first().json;
  const startNs = String(DateTime.fromISO(s.trace_start).toMillis()) + '000000';
  const endNs = String($now.toMillis()) + '000000';
  const str = (k, v) => ({ key: k, value: { stringValue: String(v == null ? '' : v) } });
  const ok = out.status === 'ok' || out.status === 'no_action';
  const attrs = [
    str('langfuse.trace.name', 'cm-email-agent'),
    str('langfuse.observation.type', 'agent'),
    str('langfuse.observation.input', typeof task === 'string' ? task : JSON.stringify(task)),
    str('langfuse.observation.output', JSON.stringify(out)),
    str('langfuse.observation.level', out.status === 'failed' ? 'ERROR' : (ok ? 'DEFAULT' : 'WARNING')),
    str('langfuse.observation.status_message', out.notes || ''),
    { key: 'langfuse.trace.tags', value: { arrayValue: { values: [{ stringValue: 'n8n' }, { stringValue: 'cm-email-agent' }] } } },
    str('langfuse.trace.metadata.workflow_id', $workflow.id),
    str('langfuse.trace.metadata.workflow_name', $workflow.name),
    str('langfuse.trace.metadata.execution_id', $execution.id),
    str('langfuse.trace.metadata.mode', $execution.mode),
    str('langfuse.trace.metadata.status', out.status),
    str('langfuse.trace.metadata.proposal_count', (out.proposed_actions || []).length),
    str('langfuse.trace.metadata.counts', JSON.stringify((out.results && out.results.counts) || {}))
  ];
  if (userId) attrs.push(str('langfuse.user.id', userId));
  return { resourceSpans: [{
    resource: { attributes: [str('service.name', 'n8n')] },
    scopeSpans: [{ scope: { name: 'n8n-cm-email-agent' }, spans: [{
      traceId: s.trace_id, spanId: s.span_id, name: 'Email agent', kind: 1,
      startTimeUnixNano: startNs, endTimeUnixNano: endNs,
      attributes: attrs,
      status: { code: out.status === 'failed' ? 2 : 1 }
    }] }]
  }] };
})()) }}
